input.sparql:
PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
PREFIX ref: <http://w3.org/ns/rev#>
SELECT ?s ?p WHERE {
  ?s a brick:Air_Handling_Unit ; brick:hasSubComponent ?c .
}

PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
PREFIX ref: <http://w3.org/ns/rev#>
SELECT ?s ?tsid WHERE {
  ?s a brick:Electrical_Power .
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
SELECT ?s ?label ?tsid WHERE {
  ?s brick:isPointOf ?ahu .
  ?ahu brick:hasPart ?c .
  OPTIONAL { ?s rdfs:label ?label }
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
SELECT ?s ?label WHERE {
  ?s a brick:Air_Handling_Unit .
  OPTIONAL { ?s rdfs:label ?label }
  OPTIONAL { ?s ref:ifcName ?label }
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
SELECT DISTINCT ?s WHERE {
  ?s a brick:Electrical_Power .
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
SELECT ?ahu ?name WHERE {
  ?ahu a brick:AHU .
  OPTIONAL { ?ahu ref:ifcName ?name }
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
SELECT ?s WHERE {
  ?s a brick:Electric_Power_Sensor .
}

PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
SELECT ?s ?tsid ?ext WHERE {
  ?s ref:hasTimeseriesId ?tsid .
  ?s ref:hasExternalReference ?ext .
}
